        /* identifiers [2] SEQUENCE OF CredentialIdentifier{{KeyIdentifiers}} */
        struct sc_path path;

        struct sc_pkcs15_der value;
};
typedef struct sc_pkcs15_cert_info sc_pkcs15_cert_info_t;

